-- ============================================================================
-- UrbanStore Seed Data (Products, Variants, Size Guides, Promos)
-- ============================================================================

-- 1. PRODUCTS

-- 2. PRODUCT VARIANTS (Per-color & per-size inventory)

-- 3. SIZE GUIDES (Anti-Zonk Reference Table)
ON CONFLICT (garment_type, size_label) DO UPDATE SET
  chest_cm = EXCLUDED.chest_cm,
  waist_cm = EXCLUDED.waist_cm,
  length_cm = EXCLUDED.length_cm,
  foot_cm = EXCLUDED.foot_cm,
  min_weight_kg = EXCLUDED.min_weight_kg,
  max_weight_kg = EXCLUDED.max_weight_kg,
  sort_order = EXCLUDED.sort_order;

-- 4. PROMOS
ON CONFLICT (code) DO UPDATE SET
  description = EXCLUDED.description,
  discount_amount = EXCLUDED.discount_amount,
  min_subtotal = EXCLUDED.min_subtotal,
  is_active = EXCLUDED.is_active;
